import type { SketchData_Variant } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { DEFAULT_ANIMATE, DEFAULT_COLOR, DEFAULT_STYLE, getOverlayZIndex } from './defaults.js';
import { type OverlayHandle, createOverlayHandle } from './overlay-handle.js';

export type { OverlayHandle } from './overlay-handle.js';

type RenderArgs = {
  style?: SketchData_Variant | string;
  color?: string;
  /**
   * Whether the draw animation should run on each redraw.
   */
  animate?: boolean;
  /**
   * Optional viewport-space rect source. When omitted, the rects are derived
   * from `target.getClientRects()` so callers don't have to compute geometry
   * for simple single-element cases.
   */
  getRects?: () => DOMRect[] | DOMRectList;
  /**
   * Optional explicit seed. When omitted, defaults to a hash of the target's
   * text content. Callers should pass an explicit seed when multiple
   * annotations may share the same text (otherwise their hand-drawn shapes
   * collide bit-for-bit).
   */
  seed?: number;
  onRendered?: () => void;
};

// Note: the `z-index` is set per-call from `opts.style` because HIGHLIGHT
// must land BEHIND text while every other annotation lands in FRONT. The
// container is made into a local stacking context so negative highlight
// overlays stay under the text but above the container background.
const OVERLAY_STYLE =
  'position: absolute; left: 0; top: 0; width: 0; height: 0; pointer-events: none;';

const POSITIONED = new Set(['relative', 'absolute', 'fixed', 'sticky']);

// djb2 — small, fast, stable string hash. Output is a non-negative 31-bit int
// matching roughjs' expected seed range.
export const stableSeedFor = (input: string): number => {
  let hash = 5381;
  for (let i = 0; i < input.length; i++) {
    hash = ((hash << 5) + hash + input.charCodeAt(i)) | 0;
  }
  return Math.abs(hash) % 2 ** 31;
};

const ensurePositioned = (element: HTMLElement) => {
  const computedStyle = window.getComputedStyle(element);
  if (!POSITIONED.has(computedStyle.position)) {
    element.style.position = 'relative';
  }
  if (computedStyle.zIndex === 'auto') {
    element.style.zIndex = '0';
  }
};

// Inline ancestors are unsafe overlay containers: their `getBoundingClientRect`
// returns the union of every line box (so e.g. a multi-line inline span across
// a justified paragraph reports `left = 47`, the page-edge of the widest
// line), but a `position: absolute; left: 0` child gets placed at the
// inline's FIRST line box origin (e.g. `left = 582` if the marked text
// starts mid-line). The two coordinate frames disagree by hundreds of
// pixels, leaving the overlay anchored to where the marked text first
// appears instead of the start of the wrapping block. We walk up until we
// find a block-level ancestor so both frames coincide. Exported so
// resize-redraw paths in the viewer reuse the same lookup.
const INLINE_DISPLAY_VALUES = new Set(['inline', 'contents']);
export const findOverlayContainer = (target: HTMLElement): HTMLElement | null => {
  let current: HTMLElement | null = target.parentElement;
  while (current && INLINE_DISPLAY_VALUES.has(window.getComputedStyle(current).display)) {
    current = current.parentElement;
  }
  return current;
};

const toRectArray = (list: DOMRect[] | DOMRectList): DOMRect[] => {
  if (Array.isArray(list)) {
    return list;
  }
  const out: DOMRect[] = [];
  for (let i = 0; i < list.length; i++) {
    out.push(list[i]!);
  }
  return out;
};

const resolveRects = (target: HTMLElement, getRects?: () => DOMRect[] | DOMRectList): DOMRect[] =>
  getRects ? toRectArray(getRects()) : toRectArray(target.getClientRects());

// Viewer entry point: not contenteditable, so the overlay can sit as a sibling
// of `target` inside its parent. The parent is made `position: relative` if it
// isn't already, so the overlay's coordinate origin is stable.
export const renderAnnotationOverlay = (
  target: HTMLElement,
  opts: RenderArgs
): OverlayHandle | null => {
  if (typeof window === 'undefined') {
    return null;
  }
  if (!target) {
    return null;
  }
  if (!target.parentElement) {
    return null;
  }
  const style = opts.style ?? DEFAULT_STYLE;
  const color = opts.color ?? DEFAULT_COLOR;
  const animate = opts.animate ?? DEFAULT_ANIMATE;
  const seed = opts.seed ?? stableSeedFor(target.textContent ?? '');

  // Closest block-level ancestor — see `findOverlayContainer` above for why
  // walking past inline ancestors matters for multi-line marked text.
  const parent = findOverlayContainer(target);
  if (!parent) {
    return null;
  }
  ensurePositioned(parent);
  const overlay = document.createElement('div');
  overlay.style.cssText = OVERLAY_STYLE;
  overlay.style.zIndex = getOverlayZIndex(style);
  parent.appendChild(overlay);

  const rects = resolveRects(target, opts.getRects);

  const handle = createOverlayHandle(overlay);
  const baseRemove = handle.remove;
  handle.remove = () => {
    baseRemove();
    overlay.remove();
  };
  // `parent` is the overlay's positioned ancestor (we just ensured
  // `position: relative` above) and is in the same scroll context as
  // `target`, so it's the right frame to translate rects into.
  handle.redraw({
    style,
    color,
    seed,
    animate,
    rects,
    container: parent,
    onRendered: opts.onRendered,
  });
  return handle;
};
