import type { SketchData_Variant } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { resolveCssColor } from './../../_shared/resolve-css-color.js';

import { ANIMATION_DURATION_MS } from './defaults.js';
import { type Rect, type RendererModule, generateShapePaths } from './draw-rough-shapes.js';

const SVGNS = 'http://www.w3.org/2000/svg';
const SKETCH_CLASS = 'sketch';
const KEYFRAMES_STYLE_ID = 'sketch-keyframes';
const KEYFRAMES = `@keyframes sketch-dash { to { stroke-dashoffset: 0 } }`;
const HOST_STYLE_ID = 'sketch-host';
// Makes every annotation's host textblock the containing block for
// its 0×0 widget div (and the SVG it owns), so the SVG tracks the
// marked text purely through CSS layout. `:has()` here replaces a
// per-annotation `Decoration.node` that previously emitted the same
// `position: relative` — halving the sketch decoration count
// removed a real per-keystroke cost in PM's `DecorationSet.forChild`.
const HOST_STYLE = `.ProseMirror :has(> [data-hook="sketch-widget"]) { position: relative; z-index: 0; }`;

// Several browsers (Chrome included) drop paths whose bounding box falls
// outside a zero-sized SVG viewport, even with `overflow: visible`. The
// rough-annotation library uses the same trick — keep a known non-zero box
// so the browser keeps painting; `overflow: visible` lets paths spill out
// freely. The value itself is arbitrary (no longer used as a coordinate
// denominator now that geometry is in container-local space).
const SVG_FIXED_CSS_SIZE = 100;

type RedrawOptions = {
  style: SketchData_Variant | string;
  color: string;
  seed: number;
  animate: boolean;
  rects: DOMRect[];
  /**
   * The DOM element whose local coordinate system the rects should be
   * translated into. Must be a positioned ancestor of the overlay SVG
   * (typically the widget's LCA — the paragraph or block container the
   * `Decoration.node` made `position: relative`). Paths are drawn in
   * this container's CSS pixels; the SVG then tracks the container
   * under any upstream layout shift via plain CSS, no `getScreenCTM`
   * round-trip and no viewport-frame arithmetic.
   */
  container: HTMLElement;
  onRendered?: () => void;
};

export type OverlayHandle = {
  /**
   * Replace the rendered paths with ones derived from the given viewport-space
   * rects, translated into `container`'s local frame. Fire-and-forget; an
   * internal generation counter ensures only the latest call survives if two
   * redraws are pending at once.
   */
  redraw: (opts: RedrawOptions) => void;
  /** Detach the overlay SVG from the DOM. */
  remove: () => void;
};

let cachedRendererPromise: Promise<RendererModule> | null = null;

const loadRenderer = (): Promise<RendererModule> => {
  if (!cachedRendererPromise) {
    cachedRendererPromise = import('roughjs/bin/renderer.js').then(
      mod => mod as unknown as RendererModule
    );
  }
  return cachedRendererPromise;
};

const ensureGlobalStyle = (id: string, css: string) => {
  if (document.getElementById(id)) {
    return;
  }
  const styleEl = document.createElement('style');
  styleEl.id = id;
  styleEl.textContent = css;
  document.head.appendChild(styleEl);
};

const ensureKeyframes = () => ensureGlobalStyle(KEYFRAMES_STYLE_ID, KEYFRAMES);
const ensureHostStyle = () => ensureGlobalStyle(HOST_STYLE_ID, HOST_STYLE);

const createOverlaySvg = (): SVGSVGElement => {
  const svg = document.createElementNS(SVGNS, 'svg') as SVGSVGElement;
  svg.setAttribute('class', SKETCH_CLASS);
  const style = svg.style;
  style.position = 'absolute';
  style.top = '0';
  style.left = '0';
  // Non-zero viewport (see `SVG_FIXED_CSS_SIZE` comment): SVG-local coords
  // are still in the *container's* CSS pixel frame because no `viewBox`
  // is set — paths render at their literal local coordinates and spill
  // beyond the 100×100 frame via `overflow: visible`.
  style.width = `${SVG_FIXED_CSS_SIZE}px`;
  style.height = `${SVG_FIXED_CSS_SIZE}px`;
  style.overflow = 'visible';
  style.pointerEvents = 'none';
  return svg;
};

// Map viewport-space rects (from `getClientRects()`) into `container`'s
// local CSS-pixel frame. The container must be a positioned ancestor of
// the overlay SVG, so subtracting its bcr gives the rect's offset inside
// the container's content box.
//
// `getBoundingClientRect` deltas are post-ancestor-transform pixels — if
// an ancestor has `transform: scale(N)` (e.g. the www-ricos stage at
// scale 1.25), the delta is already scaled by N. The SVG is inside the
// same scaled ancestor, so its rendered geometry will be scaled by N
// again — landing at scale²×wrong. We divide by the container's own
// scale factor (`bcr.width / clientWidth`) to convert post-scale viewport
// pixels back to the container's CSS pixels, which is the frame the SVG
// renders in.
//
// Exported for tests; production callers go through `redraw`.
export const translateRectsToContainerSpace = (
  container: HTMLElement,
  rects: DOMRect[]
): Rect[] => {
  const bcr = container.getBoundingClientRect();
  const cssWidth = container.clientWidth;
  const cssHeight = container.clientHeight;
  const scaleX = cssWidth > 0 && bcr.width > 0 ? bcr.width / cssWidth : 1;
  const scaleY = cssHeight > 0 && bcr.height > 0 ? bcr.height / cssHeight : scaleX;
  return rects.map(rect => ({
    x: (rect.left - bcr.left) / scaleX,
    y: (rect.top - bcr.top) / scaleY,
    w: rect.width / scaleX,
    h: rect.height / scaleY,
  }));
};

const measurePathLength = (path: SVGPathElement): number => {
  // jsdom doesn't implement `getTotalLength`; treat any failure as 0 so
  // the dasharray reveal degrades to a no-op.
  try {
    const length = path.getTotalLength();
    return Number.isFinite(length) ? length : 0;
  } catch {
    return 0;
  }
};

const clearChildren = (node: Element) => {
  while (node.firstChild) {
    node.removeChild(node.firstChild);
  }
};

const createPath = (color: string, d: string, strokeWidth: number): SVGPathElement => {
  const path = document.createElementNS(SVGNS, 'path') as SVGPathElement;
  path.setAttribute('d', d);
  path.setAttribute('fill', 'none');
  path.setAttribute('stroke', resolveCssColor(color) ?? color);
  path.setAttribute('stroke-width', String(strokeWidth));
  return path;
};

// Per-rect dash animation: split duration across paths proportional to
// length with cumulative delay so strokes draw in sequence. `groupDelay`
// staggers multi-line rects. Mirrors rough-annotation's render.ts.
const animatePaths = (paths: SVGPathElement[], groupDelay: number, totalDuration: number) => {
  if (paths.length === 0) {
    return;
  }
  const lengths = paths.map(measurePathLength);
  const totalLength = lengths.reduce((sum, length) => sum + length, 0);
  let offset = 0;
  paths.forEach((path, index) => {
    const length = lengths[index]!;
    const duration = totalLength > 0 ? totalDuration * (length / totalLength) : 0;
    path.style.strokeDasharray = String(length);
    path.style.strokeDashoffset = String(length);
    path.style.animation = `sketch-dash ${duration}ms ease-out ${groupDelay + offset}ms forwards`;
    offset += duration;
  });
};

const renderInto = (
  svg: SVGSVGElement,
  renderer: RendererModule,
  opts: RedrawOptions,
  precomputedLocalRects?: Rect[]
): SVGPathElement[] => {
  clearChildren(svg);
  if (opts.rects.length === 0) {
    return [];
  }
  // Translate at call-time when caller hasn't supplied a snapshot — but
  // when the redraw is async (first renderer load), the caller passes
  // `precomputedLocalRects` measured in the SAME frame as `opts.rects`
  // so a layout shift between `redraw()` and the awaited render
  // can't desync the rects from the container origin.
  const localRects =
    precomputedLocalRects ?? translateRectsToContainerSpace(opts.container, opts.rects);
  // Width-proportional duration across rects, mirroring rough-annotation.
  const totalWidth = localRects.reduce((sum, r) => sum + r.w, 0);
  const allPaths: SVGPathElement[] = [];
  let cumulativeDelay = 0;
  for (const rect of localRects) {
    const shapePaths = generateShapePaths({
      renderer,
      rect,
      style: opts.style,
      seed: opts.seed,
    });
    const rectPaths = shapePaths.map(({ d, strokeWidth }) =>
      createPath(opts.color, d, strokeWidth)
    );
    rectPaths.forEach(p => svg.appendChild(p));
    const rectDuration = totalWidth > 0 ? ANIMATION_DURATION_MS * (rect.w / totalWidth) : 0;
    if (opts.animate) {
      animatePaths(rectPaths, cumulativeDelay, rectDuration);
    }
    cumulativeDelay += rectDuration;
    allPaths.push(...rectPaths);
  }
  return allPaths;
};

export const createOverlayHandle = (overlay: HTMLElement): OverlayHandle => {
  ensureKeyframes();
  ensureHostStyle();
  const svg = createOverlaySvg();
  overlay.appendChild(svg);
  let renderer: RendererModule | null = null;
  let generation = 0;

  const draw = (
    opts: RedrawOptions,
    requestGeneration: number,
    r: RendererModule,
    precomputedLocalRects?: Rect[]
  ) => {
    if (requestGeneration !== generation) {
      return;
    }
    renderInto(svg, r, opts, precomputedLocalRects);
    opts.onRendered?.();
  };

  return {
    redraw: opts => {
      generation += 1;
      const current = generation;
      if (renderer) {
        draw(opts, current, renderer);
        return;
      }
      // First call must wait on the renderer chunk; snapshot the local
      // rects NOW (same frame as the caller measured `opts.rects`) so
      // any layout shift before the promise resolves can't desync the
      // container origin from the rect coords.
      const localRects = translateRectsToContainerSpace(opts.container, opts.rects);
      void loadRenderer().then(r => {
        renderer = r;
        draw(opts, current, r, localRects);
      });
    },
    remove: () => {
      generation += 1;
      svg.remove();
    },
  };
};
