import { SKETCH_DATA_HOOK } from './data-hooks.js';
import { DEFAULT_ANIMATE, DEFAULT_COLOR, DEFAULT_STYLE } from './defaults.js';
import {
  canMergeAdjacentByStructure,
  getAnnotationSignature,
  isCrossParagraphMergeStyle,
} from './merge-rules.js';
import { getOverlayRects } from './rect-utils.js';
import {
  type OverlayHandle,
  findOverlayContainer,
  renderAnnotationOverlay,
  stableSeedFor,
} from './render-sketch.js';

const BLOCKING_CONTENT_SELECTOR = 'img,video,iframe,canvas,svg:not(.sketch)';

const scheduledDocuments = new WeakSet<Document>();

declare global {
  interface Window {
    ricosSketchesReady?: boolean;
  }
}

type AnnotationGroup = HTMLElement[];

type MountedOverlayEntry = {
  group: AnnotationGroup;
  style: string;
  color: string;
  seed: number;
  handle: OverlayHandle;
  animate: boolean;
  wasVisible: boolean;
};
type RootRenderState = {
  observer: ResizeObserver | null;
  mountedOverlays: MountedOverlayEntry[];
  resizeFrame: number | null;
  // Skip the synthetic first ResizeObserver callback (fires on `observe()`
  // with the current size); otherwise it'd clobber the initial animation
  // with a static `animate: false` redraw.
  hasObservedInitialResize: boolean;
};
const rootStates = new WeakMap<HTMLElement, RootRenderState>();

type OverlayEntry = {
  key: string;
  group: AnnotationGroup;
  style: string;
  color: string;
  seed: number;
  handle: OverlayHandle | null;
  observationRoot: HTMLElement;
  pendingObserver: IntersectionObserver | null;
};
const overlaysByAnchor = new Map<HTMLElement, OverlayEntry>();

const getSignature = (target: HTMLElement) =>
  getAnnotationSignature({
    style: target.getAttribute('data-style'),
    color: target.getAttribute('data-color'),
    animate: target.getAttribute('data-animate') !== 'false',
  });

// Walked past instead of using `getComputedStyle().display` — the viewer's
// `<span class="paragraph__child">` wrapper carries `display: block`, which
// would otherwise make `findBlockRoot` stop short of the real paragraph
// and break cross-paragraph merging.
const INLINE_TAG_NAMES = new Set([
  'SPAN',
  'A',
  'B',
  'I',
  'U',
  'EM',
  'STRONG',
  'MARK',
  'SMALL',
  'CODE',
  'KBD',
  'SAMP',
  'VAR',
  'SUB',
  'SUP',
  'ABBR',
  'CITE',
  'Q',
  'S',
  'DEL',
  'INS',
  'BR',
  'WBR',
]);

const findBlockRoot = (target: HTMLElement): HTMLElement => {
  let current: HTMLElement | null = target.parentElement;
  while (current?.parentElement && INLINE_TAG_NAMES.has(current.tagName)) {
    current = current.parentElement;
  }
  return current ?? target.parentElement ?? target;
};

// Viewer-side equivalent of the editor's `getParagraphInfo` rejecting
// non-paragraph blocks. Ricos paragraphs always render as `<p>`; headings,
// list-items, captions etc. use other tags.
const isParagraphBlock = (block: HTMLElement): boolean => block.tagName === 'P';

// Ricos wraps each block in a per-block `<div data-breakout="...">`. Two
// paragraphs in the same card each get their own wrapper but share the
// card's content container as their real parent. Walk past the wrappers to
// match the editor's "same direct PM parent" check.
const findStructuralContainer = (block: HTMLElement): HTMLElement | null => {
  let current: HTMLElement | null = block.parentElement;
  while (current && current.hasAttribute('data-breakout')) {
    current = current.parentElement;
  }
  return current;
};

const getCommonAncestor = (from: globalThis.Node, to: globalThis.Node): globalThis.Node => {
  const ancestors = new Set<globalThis.Node>();
  let current: globalThis.Node | null = from;
  while (current) {
    ancestors.add(current);
    current = current.parentNode;
  }
  current = to;
  while (current) {
    if (ancestors.has(current)) {
      return current;
    }
    current = current.parentNode;
  }
  return document.body;
};

// JTD hardBreak is encoded as a text node containing a literal `\n`.
const isSoftBreakTextNode = (node: globalThis.Node): boolean =>
  node.nodeType === globalThis.Node.TEXT_NODE && node.textContent === '\n';

const hasContentBetween = (from: HTMLElement, to: HTMLElement, style: string): boolean => {
  const allowHardBreak = isCrossParagraphMergeStyle(style);
  const root = getCommonAncestor(from, to);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
  let isBetweenTargets = false;
  while (walker.nextNode()) {
    const current = walker.currentNode;
    if (current === from) {
      isBetweenTargets = true;
      continue;
    }
    if (current === to) {
      return false;
    }
    if (!isBetweenTargets || from.contains(current) || to.contains(current)) {
      continue;
    }
    if (current.nodeType === globalThis.Node.TEXT_NODE && current.textContent) {
      if (allowHardBreak && isSoftBreakTextNode(current)) {
        continue;
      }
      return true;
    }
    if (current instanceof HTMLElement && current.matches(BLOCKING_CONTENT_SELECTOR)) {
      return true;
    }
  }
  return false;
};

const canMergeSpans = (from: HTMLElement, to: HTMLElement, style: string): boolean => {
  if (hasContentBetween(from, to, style)) {
    return false;
  }
  const fromBlock = findBlockRoot(from);
  const toBlock = findBlockRoot(to);
  if (fromBlock === toBlock) {
    return true;
  }
  if (!isParagraphBlock(fromBlock) || !isParagraphBlock(toBlock)) {
    return false;
  }
  const fromContainer = findStructuralContainer(fromBlock);
  const toContainer = findStructuralContainer(toBlock);
  return canMergeAdjacentByStructure(style, {
    sameBlock: false,
    // Object identity: two `<li>`s under the same `<ul>` are distinct
    // element instances, so cross list-item merging is naturally rejected.
    sameStructuralContainer: !!fromContainer && fromContainer === toContainer,
  });
};

const findObservationRoot = (target: HTMLElement): HTMLElement => {
  const blockRoot = findBlockRoot(target);
  const structural = findStructuralContainer(blockRoot);
  return structural ?? blockRoot ?? (target.ownerDocument?.body as HTMLElement);
};

// Spans inside an editable contenteditable region are owned by ProseMirror
// (handled by `tiptap.ts`'s overlay controller). Touching them would inject
// DOM that PM reconciles away. We use the *closest* contenteditable
// ancestor so React-rendered islands inside the editor (card content,
// node-views with `contenteditable="false"`) still get annotated.
const isInsideEditableRegion = (el: HTMLElement): boolean => {
  const nearest = el.closest('[contenteditable]');
  if (!nearest) {
    return false;
  }
  const value = nearest.getAttribute('contenteditable');
  return value === 'true' || value === '';
};

const getRoughSpans = (root: ParentNode): HTMLElement[] =>
  Array.from(root.querySelectorAll<HTMLElement>(`span[data-hook="${SKETCH_DATA_HOOK}"]`)).filter(
    span => !isInsideEditableRegion(span)
  );

const buildAnnotationGroups = (spans: HTMLElement[]): AnnotationGroup[] => {
  const groups: AnnotationGroup[] = [];
  for (const span of spans) {
    const previousGroup = groups[groups.length - 1];
    const previousSpan = previousGroup?.[previousGroup.length - 1];
    const style = span.getAttribute('data-style') || DEFAULT_STYLE;
    if (
      previousGroup &&
      previousSpan &&
      getSignature(previousSpan) === getSignature(span) &&
      canMergeSpans(previousSpan, span, style)
    ) {
      previousGroup.push(span);
      continue;
    }
    groups.push([span]);
  }
  return groups;
};

const getAnimate = (target: HTMLElement) => target.getAttribute('data-animate') !== 'false';

let spanIdCounter = 0;
const spanIds = new WeakMap<HTMLElement, string>();
const getSpanId = (span: HTMLElement): string => {
  const existing = spanIds.get(span);
  if (existing !== undefined) {
    return existing;
  }
  const id = String(++spanIdCounter);
  spanIds.set(span, id);
  return id;
};

const computeAnnotationGroupKey = (group: AnnotationGroup): string => {
  const target = group[0]!;
  const style = target.getAttribute('data-style') || DEFAULT_STYLE;
  const color = target.getAttribute('data-color') || DEFAULT_COLOR;
  const animate = target.getAttribute('data-animate') || String(DEFAULT_ANIMATE);
  return `${style}|${color}|${animate}|${group.map(getSpanId).join(',')}`;
};

const teardownOverlay = (entry: OverlayEntry) => {
  entry.pendingObserver?.disconnect();
  entry.pendingObserver = null;
  if (entry.handle) {
    // Drop from rootState first so a queued resize redraw doesn't call
    // `handle.redraw` on a freshly-removed handle.
    const rootState = rootStates.get(entry.observationRoot);
    if (rootState) {
      rootState.mountedOverlays = rootState.mountedOverlays.filter(g => g.handle !== entry.handle);
    }
    entry.handle.remove();
    entry.handle = null;
  }
};

const buildAnnotationGroupSeedText = (group: AnnotationGroup) =>
  group.map(span => span.textContent ?? '').join('\n');

const createOverlay = (group: AnnotationGroup, onRendered?: () => void): OverlayEntry | null => {
  const target = group[0];
  if (!target || !target.isConnected) {
    return null;
  }

  const style = target.getAttribute('data-style') || DEFAULT_STYLE;
  const color = target.getAttribute('data-color') || DEFAULT_COLOR;
  const animate = getAnimate(target);
  const seedText = buildAnnotationGroupSeedText(group);
  const seed = stableSeedFor(seedText);
  const observationRoot = findObservationRoot(target);
  const entry: OverlayEntry = {
    key: computeAnnotationGroupKey(group),
    group,
    style,
    color,
    seed,
    handle: null,
    observationRoot,
    pendingObserver: null,
  };

  const render = (shouldAnimate: boolean) => {
    if (!target.isConnected) {
      return;
    }
    const handle = renderAnnotationOverlay(target, {
      style,
      color,
      animate: shouldAnimate,
      seed,
      getRects: () => getAnnotationGroupRects(group, style),
      onRendered,
    });
    if (handle) {
      entry.handle = handle;
      registerMountedOverlay(observationRoot, {
        group,
        style,
        color,
        seed,
        handle,
        animate,
        // Seed from the rects we just drew so the next resize doesn't
        // misread this as a hidden→visible transition and replay.
        wasVisible: isAnnotationGroupVisible(getAnnotationGroupRects(group, style)),
      });
    }
  };

  if (animate && typeof IntersectionObserver !== 'undefined') {
    entry.pendingObserver = new IntersectionObserver(
      entries => {
        if (entries.some(e => e.isIntersecting)) {
          entry.pendingObserver?.disconnect();
          entry.pendingObserver = null;
          render(true);
        }
      },
      { threshold: 0.1 }
    );
    entry.pendingObserver.observe(target);
  } else {
    render(false);
  }

  return entry;
};

const promoteMergedOverlayAnchors = (group: AnnotationGroup) => {
  for (let i = 1; i < group.length; i++) {
    const promoted = overlaysByAnchor.get(group[i]!);
    if (promoted) {
      teardownOverlay(promoted);
      overlaysByAnchor.delete(group[i]!);
    }
  }
};

const collectAnnotationGroups = (doc: Document): AnnotationGroup[] => {
  const spans = getRoughSpans(doc.body).filter(span => span.isConnected);
  return buildAnnotationGroups(spans);
};

const createRenderCompletionTracker = (doc: Document) => {
  let pendingRenders = 0;
  let renderScanComplete = false;
  const markGroupRendered = () => {
    pendingRenders -= 1;
    if (renderScanComplete && pendingRenders === 0) {
      markSketchesReady(doc);
    }
  };
  return {
    markGroupRendered,
    trackPendingRender: () => {
      pendingRenders += 1;
    },
    completeRenderScan: () => {
      renderScanComplete = true;
      if (pendingRenders === 0) {
        markSketchesReady(doc);
      }
    },
  };
};

const syncOverlayForGroup = (
  group: AnnotationGroup,
  trackPendingRender: () => void,
  markGroupRendered: () => void
): HTMLElement | null => {
  const anchor = group[0];
  if (!anchor) {
    return null;
  }
  promoteMergedOverlayAnchors(group);
  const key = computeAnnotationGroupKey(group);
  const existing = overlaysByAnchor.get(anchor);
  if (existing && existing.key === key) {
    return anchor;
  }
  if (existing) {
    teardownOverlay(existing);
    overlaysByAnchor.delete(anchor);
  }
  trackPendingRender();
  const entry = createOverlay(group, markGroupRendered);
  if (entry) {
    overlaysByAnchor.set(anchor, entry);
  } else {
    markGroupRendered();
  }
  return anchor;
};

const dropStaleOverlays = (liveAnchors: Set<HTMLElement>) => {
  for (const [anchor, entry] of overlaysByAnchor) {
    if (!liveAnchors.has(anchor) || !anchor.isConnected) {
      teardownOverlay(entry);
      overlaysByAnchor.delete(anchor);
    }
  }
};

const reconcileOverlays = (doc: Document) => {
  const renderCompletion = createRenderCompletionTracker(doc);
  const liveAnchors = new Set<HTMLElement>();

  for (const group of collectAnnotationGroups(doc)) {
    const anchor = syncOverlayForGroup(
      group,
      renderCompletion.trackPendingRender,
      renderCompletion.markGroupRendered
    );
    if (anchor) {
      liveAnchors.add(anchor);
    }
  }

  dropStaleOverlays(liveAnchors);
  renderCompletion.completeRenderScan();
};

const markSketchesPending = (doc: Document) => {
  const view = doc.defaultView;
  if (view) {
    view.ricosSketchesReady = false;
  }
};

const markSketchesReady = (doc: Document) => {
  const view = doc.defaultView;
  if (!view) {
    return;
  }
  view.requestAnimationFrame(() => {
    view.requestAnimationFrame(() => {
      view.ricosSketchesReady = true;
    });
  });
};

const isAnnotationGroupVisible = (rects: DOMRect[]): boolean =>
  rects.some(r => r.width > 0 && r.height > 0);

const shouldReplayRevealAnimation = (entry: MountedOverlayEntry, rects: DOMRect[]): boolean =>
  entry.animate && isAnnotationGroupVisible(rects) && !entry.wasVisible;

const redrawRootOverlays = (root: HTMLElement) => {
  const state = rootStates.get(root);
  if (!state) {
    return;
  }
  state.mountedOverlays = state.mountedOverlays.filter(({ group, handle }) => {
    const stillConnected = group.some(span => span.isConnected);
    if (!stillConnected) {
      handle.remove();
    }
    return stillConnected;
  });
  for (const entry of state.mountedOverlays) {
    const { group, style, color, seed, handle } = entry;
    const rects = getAnnotationGroupRects(group, style);
    const visible = isAnnotationGroupVisible(rects);
    const shouldAnimate = shouldReplayRevealAnimation(entry, rects);
    entry.wasVisible = visible;
    const anchor = group[0];
    if (!anchor) {
      continue;
    }
    const container = findOverlayContainer(anchor);
    if (!container) {
      continue;
    }
    handle.redraw({
      style,
      color,
      seed,
      animate: shouldAnimate,
      rects,
      container,
    });
  }
};

const ensureRootResizeObserver = (root: HTMLElement): RootRenderState => {
  const existing = rootStates.get(root);
  if (existing) {
    return existing;
  }
  const state: RootRenderState = {
    observer: null,
    mountedOverlays: [],
    resizeFrame: null,
    hasObservedInitialResize: false,
  };
  if (typeof ResizeObserver !== 'undefined') {
    state.observer = new ResizeObserver(() => {
      // Skip the synthetic first fire (would clobber the in-flight
      // initial animation with a static `animate: false` redraw).
      if (!state.hasObservedInitialResize) {
        state.hasObservedInitialResize = true;
        return;
      }
      if (state.resizeFrame !== null) {
        return;
      }
      state.resizeFrame = window.requestAnimationFrame(() => {
        state.resizeFrame = null;
        if (!root.isConnected) {
          state.observer?.disconnect();
          rootStates.delete(root);
          return;
        }
        redrawRootOverlays(root);
      });
    });
    state.observer.observe(root);
  }
  rootStates.set(root, state);
  return state;
};

const registerMountedOverlay = (root: HTMLElement, overlay: MountedOverlayEntry) => {
  const state = ensureRootResizeObserver(root);
  state.mountedOverlays = state.mountedOverlays.filter(g => g.group[0] !== overlay.group[0]);
  state.mountedOverlays.push(overlay);
};

const getAnnotationGroupRects = (group: AnnotationGroup, style: string): DOMRect[] => {
  const rects: DOMRect[] = [];
  for (const span of group) {
    const list = span.getClientRects();
    for (let i = 0; i < list.length; i++) {
      rects.push(list[i]!);
    }
  }
  return getOverlayRects(style, rects);
};

export const scheduleSketchRender = (target: HTMLElement) => {
  const doc = target.ownerDocument;
  if (!doc) {
    return;
  }
  markSketchesPending(doc);
  if (scheduledDocuments.has(doc)) {
    return;
  }
  scheduledDocuments.add(doc);
  (doc.defaultView ?? window).requestAnimationFrame(() => {
    scheduledDocuments.delete(doc);
    reconcileOverlays(doc);
  });
};
