import type { SketchData_Variant } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

const mergeRectsByLine = (list: DOMRect[] | DOMRectList): DOMRect[] => {
  const rects: DOMRect[] = [];
  for (let i = 0; i < list.length; i++) {
    rects.push(list[i]!);
  }
  const out: DOMRect[] = [];
  const sortedRects = rects.sort((a, b) => a.top - b.top || a.left - b.left);
  let line: { left: number; top: number; right: number; bottom: number } | null = null;
  for (const rect of sortedRects) {
    const centerY = rect.top + rect.height / 2;
    if (!line || centerY < line.top || centerY > line.bottom) {
      if (line) {
        out.push(new DOMRect(line.left, line.top, line.right - line.left, line.bottom - line.top));
      }
      line = { left: rect.left, top: rect.top, right: rect.right, bottom: rect.bottom };
      continue;
    }
    line.left = Math.min(line.left, rect.left);
    line.top = Math.min(line.top, rect.top);
    line.right = Math.max(line.right, rect.right);
    line.bottom = Math.max(line.bottom, rect.bottom);
  }
  if (line) {
    out.push(new DOMRect(line.left, line.top, line.right - line.left, line.bottom - line.top));
  }
  return out;
};

const mergeRectsToBoundingRect = (list: DOMRect[] | DOMRectList): DOMRect[] => {
  if (list.length === 0) {
    return [];
  }
  let left = Infinity;
  let top = Infinity;
  let right = -Infinity;
  let bottom = -Infinity;
  for (let i = 0; i < list.length; i++) {
    const rect = list[i]!;
    left = Math.min(left, rect.left);
    top = Math.min(top, rect.top);
    right = Math.max(right, rect.right);
    bottom = Math.max(bottom, rect.bottom);
  }
  return [new DOMRect(left, top, right - left, bottom - top)];
};

// Box-like styles wrap the entire mark as one shape, so
// they get a single bounding rect. Stroke-like styles render once per visual
// line, so they get the per-line merge.
export const getOverlayRects = (
  style: SketchData_Variant | string,
  list: DOMRect[] | DOMRectList
): DOMRect[] => {
  if (style === 'BOX' || style === 'CIRCLE') {
    return mergeRectsToBoundingRect(list);
  }
  return mergeRectsByLine(list);
};
